entries[104048] = { ["name"] = "Glyphe 'Regenerative Magie'", ["text"] = "Erhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nFalls Eure Fähigkeit 'Antimagische Hülle' ihre volle Dauer lang bestehen bleibt, wird die Abklingzeit abhängig von der noch verbleibenden Absorptionsmenge um bis zu 50% verringert.\nVerkaufspreis:" }
entries[104049] = { ["name"] = "Glyphe 'Eitriges Blut'", ["text"] = "Erhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Siedendes Blut' behandelt jetzt alle Ziele, als wären sie mit 'Blutseuche' oder 'Frostfieber' infiziert.\nVerkaufspreis:" }
entries[104050] = { ["name"] = "Glyphe 'Gottesschild'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDas Entfernen schädlicher Effekte mittels 'Gottesschild' heilt Euch pro entferntem Effekt um 10%. Diese Heilung kann 50% Eurer Maximalgesundheit nicht übersteigen.\nVerkaufspreis:" }
entries[104051] = { ["name"] = "Glyphe 'Hand der Aufopferung'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Hand der Aufopferung' leitet keinen Schaden mehr zu Euch um.\nVerkaufspreis:" }
entries[104052] = { ["name"] = "Glyphe 'Reinigung'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie erfolgreiche Anwendung von 'Reinigen' gewährt jetzt eine Aufladung von 'Waffe des Mahlstroms'.\nVerkaufspreis:" }
entries[104053] = { ["name"] = "Glyphe 'Ewige Erde'", ["text"] = "Erhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blitzschlag' hat eine Chance, Eurem aktiven 'Erdschild' eine Aufladung hinzuzufügen. Euer 'Erdschild' kann jedoch nicht über mehr als 9 Aufladungen verfügen.\nVerkaufspreis:" }
entries[104054] = { ["name"] = "Glyphe 'Verwüstung'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Zauber 'Verwüstung' erhält 3 zusätzliche Aufladungen, die Abklingzeit wird jedoch um 35 Sek. erhöht.\nVerkaufspreis:" }
entries[104055] = { ["name"] = "Glyphe 'Aufspießender Wurf'", ["text"] = "Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Heldenhafter Wurf' lässt jetzt eine Axt im Ziel zurück, die aufgesammelt werden kann, wenn Ihr Euch dem Ziel auf 5 Meter nähert, wodurch die Abklingzeit von 'Heldenhafter Wurf' zurückgesetzt wird. Dieser Effekt tritt nur ein, wenn 'Heldenhafter Wurf' aus mehr als 10 Metern Entfernung vom Ziel eingesetzt wurde.\nVerkaufspreis:" }
entries[104056] = { ["name"] = "Glyphe 'Henker'", ["text"] = "Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDas Töten eines Gegners mittels 'Hinrichten' gewährt Euch 30 Wut.\nVerkaufspreis:" }
entries[104099] = { ["name"] = "Glyphe 'Skelett'", ["text"] = "Geringe Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Totenerweckung' beschwört jetzt ein Skelett anstatt eines Ghuls.\nVerkaufspreis:" }
entries[104101] = { ["name"] = "Glyphe 'Langer Winter'", ["text"] = "Geringe Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Effekt Eurer Fähigkeit 'Horn des Winters' hält jetzt 1 Std. lang an.\nVerkaufspreis:" }
entries[104102] = { ["name"] = "Glyphe 'Sprießender Pilz'", ["text"] = "Geringe Glyphe\nKlassen: Druide\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Wildpilze können jetzt auf dem Boden anstatt unter einem Ziel platziert werden.\nVerkaufspreis:" }
entries[104103] = { ["name"] = "Glyphe 'Eins mit der Natur'", ["text"] = "Geringe Glyphe\nKlassen: Druide\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nGewährt Euch die Fähigkeit, Euch an einen zufälligen naturbelassenen Ort zu teleportieren.\nVerkaufspreis:" }
entries[104104] = { ["name"] = "Glyphe 'Unbändiger Elementar'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch einen unbändigen Wasserelementar ersetzt.\nVerkaufspreis:" }
entries[104105] = { ["name"] = "Glyphe 'Verdampfen'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Wasserelementars um 40%.\nVerkaufspreis:" }
entries[104106] = { ["name"] = "Glyphe 'Kondensation'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Größe Eures Wasserelementars um 40%.\nVerkaufspreis:" }
entries[104107] = { ["name"] = "Glyphe 'Exorzist'", ["text"] = "Geringe Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Exorzismus' vertreibt jetzt visuell das Böse aus dem Ziel.\nVerkaufspreis:" }
entries[104108] = { ["name"] = "Glyphe 'Säule des Lichts'", ["text"] = "Geringe Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nKritische Treffer Eurer Heilzauber bei anderen Spielercharakteren erzeugen kurzzeitig eine Lichtsäule an deren Standort.\nVerkaufspreis:" }
entries[104109] = { ["name"] = "Glyphe 'Engel'", ["text"] = "Geringe Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Heilzauber gewähren Euch vorübergehend Engelsflügel. (100ms Abklingzeit)\nVerkaufspreis:" }
entries[104110] = { ["name"] = "Merkwürdige bronzene Taschenuhr", ["text"] = "Questgegenstand\nEinzigartig\nBenötigt Stufe 90\nBenutzen: Bringt Euch zu Behüterin Alundra auf der Zeitlosen Insel.\n\"Die Stundenmarkierungen sind unlesbar und es schmerzt die Augen, sich auf sie zu konzentrieren.\"" }
entries[104111] = { ["name"] = "Elixier der wandernden Geister", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Nehmt die Gestalt eines Helden des Goldenen Lotus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
