entries[104113] = { ["name"] = "Merkwürdige bronzene Taschenuhr", ["text"] = "Questgegenstand\nEinzigartig\nBenötigt Stufe 90\nBenutzen: Bringt Euch zu Behüterin Lara auf der Zeitlosen Insel.\n\"Die Stundenmarkierungen sind unlesbar und es schmerzt die Augen, sich auf sie zu konzentrieren.\"" }
entries[104114] = { ["name"] = "Merkwürdiges tickendes Paket", ["text"] = "Benötigt Stufe 90\n<Zum Öffnen rechtsklicken>" }
entries[104115] = { ["name"] = "Nebelgefüllte Geistlaterne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nBenutzen: Beschwört das Schreckensschiff Vazuvius aus den Tiefen.\n\"Ein seltsamer, scheinbar lebender Nebel ist in dieser kleinen Laterne gefangen.\"" }
entries[104120] = { ["name"] = "Glyphe 'Sha'", ["text"] = "Geringe Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist oder Euren Geistbeuger in eine Sha-Bestie.\nVerkaufspreis:" }
entries[104121] = { ["name"] = "Glyphe 'Verschobenes Aussehen'", ["text"] = "Geringe Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Leerenverschiebung' lässt Euch und das Ziel für einige Sekunden das Aussehen tauschen.\n\nWirkt sich nicht auf berittene Spielercharaktere aus.\nVerkaufspreis:" }
entries[104122] = { ["name"] = "Glyphe 'Inspirierte Hymnen'", ["text"] = "Geringe Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Hymnen kanalisiert, erscheint ein Geist über Euch.\nVerkaufspreis:" }
entries[104123] = { ["name"] = "Glyphe 'Kopfjäger'", ["text"] = "Geringe Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Werfen' und 'Tödlicher Wurf' werfen jetzt immer Äxte, unabhängig von der ausgerüsteten Waffe.\nVerkaufspreis:" }
entries[104124] = { ["name"] = "Glyphe 'Verbesserte Ablenkung'", ["text"] = "Geringe Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Ablenkung' erstellt jetzt eine Attrappe am Zielort.\nVerkaufspreis:" }
entries[104126] = { ["name"] = "Glyphe 'Geisterraptoren'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Geisterwölfe werden durch Geisterraptoren ersetzt.\nVerkaufspreis:" }
entries[104127] = { ["name"] = "Glyphe 'Beistand der Ahnen'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn ein Spielercharakter mittels 'Geist der Ahnen' wiederbelebt wird, folgt ihm ein Ahnengeist für kurze Zeit.\nVerkaufspreis:" }
entries[104128] = { ["name"] = "Glyphe 'Geisterwolf'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Geisterwolf' kann jetzt gewirkt werden, während Ihr ein Geist seid.\nVerkaufspreis:" }
entries[104129] = { ["name"] = "Glyphe 'Flammenschlangen'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Totem der Verbrennung' hat jetzt die Erscheinung von Vol'jins 'Schlangenzauberschutz'.\nVerkaufspreis:" }
