entries[104131] = { ["name"] = "Glyphe 'Elementarfamiliare'", ["text"] = "Geringe Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBeschwört einen zufälligen Feuer-, Wasser- oder Erdfamiliar. Familiare unterschiedlicher Typen neigen dazu, sich gegenseitig zu bekämpfen.\nVerkaufspreis:" }
