entries[104135] = { ["name"] = "Glyphe 'Wütender Wirbelwind'", ["text"] = "Geringe Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Wirbelwind' gewährt Euch im Verlauf von 6 Sek. 15 Wut. Während dieser Zeit erzeugen Eure automatischen Angriffe jedoch keine Wut.\nVerkaufspreis:" }
