entries[104197] = { ["name"] = "Technik: Glyphe 'Schneller Tod'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Schneller Tod' schreibt.\n\nGlyphe 'Schneller Tod'\nErhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Tempoeffekt Eurer Fähigkeit 'Seelenernter' erhöht ebenfalls Euer Bewegungstempo um 30%.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104198] = { ["name"] = "Ausrüstung des Mantisartefaktjägers", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält ein Sonar für Mantisartefakte, durch das sämtliche neue Ausgrabungsstätten, die Ihr in Pandaria entdeckt, einen Tag lang zu Mantisausgrabungsstätten werden. Enthält außerdem eine Karte des Lehrensuchers.\"\n<Zum Öffnen rechtsklicken>" }
entries[104202] = { ["name"] = "Flipps", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Flipps, den boxenden Ho-zen beschwören oder wieder freigeben.\nVerkaufspreis:" }
entries[104208] = { ["name"] = "Zügel von Galakras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie Ihr eine Brut von Galakras beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Brut von Galakras oder gibt sie wieder frei. Das ist ein Flugreittier." }
entries[104209] = { ["name"] = "Technik: Glyphe 'Lautes Horn'", ["text"] = "Benötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Lautes Horn' schreibt.\n\nGlyphe 'Lautes Horn'\nErhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Horn des Winters' erzeugt jetzt 10 zusätzliche Runenmacht, die Abklingzeit wird jedoch um 100% erhöht.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104210] = { ["name"] = "Technik: Glyphe 'Regenerative Magie'", ["text"] = "Benötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Regenerative Magie' schreibt.\n\nGlyphe 'Regenerative Magie'\nErhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nFalls Eure Fähigkeit 'Antimagische Hülle' ihre volle Dauer lang bestehen bleibt, wird die Abklingzeit abhängig von der noch verbleibenden Absorptionsmenge um bis zu 50% verringert.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
