entries[104212] = { ["name"] = "Technik: Glyphe 'Gottesschild'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Gottesschild' schreibt.\n\nGlyphe 'Gottesschild'\nErhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDas Entfernen schädlicher Effekte mittels 'Gottesschild' heilt Euch pro entferntem Effekt um 10%. Diese Heilung kann 50% Eurer Maximalgesundheit nicht übersteigen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104213] = { ["name"] = "Technik: Glyphe 'Hand der Aufopferung'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Hand der Aufopferung' schreibt.\n\nGlyphe 'Hand der Aufopferung'\nErhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Hand der Aufopferung' leitet keinen Schaden mehr zu Euch um.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104214] = { ["name"] = "Technik: Glyphe 'Reinigung'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Reinigung' schreibt.\n\nGlyphe 'Reinigung'\nErhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie erfolgreiche Anwendung von 'Reinigen' gewährt jetzt eine Aufladung von 'Waffe des Mahlstroms'.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104215] = { ["name"] = "Technik: Glyphe 'Ewige Erde'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Ewige Erde' schreibt.\n\nGlyphe 'Ewige Erde'\nErhebliche Glyphe\nKlassen: Schamane\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blitzschlag' hat eine Chance, Eurem aktiven 'Erdschild' eine Aufladung hinzuzufügen. Euer 'Erdschild' kann jedoch nicht über mehr als 9 Aufladungen verfügen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104216] = { ["name"] = "Technik: Glyphe 'Verwüstung'", ["text"] = "Benötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Verwüstung' schreibt.\n\nGlyphe 'Verwüstung'\nErhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Zauber 'Verwüstung' erhält 3 zusätzliche Aufladungen, die Abklingzeit wird jedoch um 35 Sek. erhöht.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104217] = { ["name"] = "Technik: Glyphe 'Aufspießender Wurf'", ["text"] = "Benötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Aufspießender Wurf' schreibt.\n\nGlyphe 'Aufspießender Wurf'\nErhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Heldenhafter Wurf' lässt jetzt eine Axt im Ziel zurück, die aufgesammelt werden kann, wenn Ihr Euch dem Ziel auf 5 Meter nähert, wodurch die Abklingzeit von 'Heldenhafter Wurf' zurückgesetzt wird. Dieser Effekt tritt nur ein, wenn 'Heldenhafter Wurf' aus mehr als 10 Metern Entfernung vom Ziel eingesetzt wurde.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
