entries[104279] = { ["name"] = "Technik: Glyphe 'Jagdrudel'", ["text"] = "Benötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Jagdrudel' schreibt.\n\nGlyphe 'Jagdrudel'\nErhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert den Radius von 'Aspekt des Rudels' um 33 Meter.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104280] = { ["name"] = "Technik: Glyphe 'Konzentriertes Feuer'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Konzentriertes Feuer' schreibt.\n\nGlyphe 'Konzentriertes Feuer'\nGeringe Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nAufladungen von 'Konzentriertes Feuer' gewähren Euch für jede aktive Aufladung einen visuellen Effekt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104281] = { ["name"] = "Technik: Glyphe 'Hartnäckige Tarnung'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Hartnäckige Tarnung' schreibt.\n\nGlyphe 'Hartnäckige Tarnung'\nErhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Camouflage' verringert den erlittenen Zauberschaden um 10%.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104282] = { ["name"] = "Technik: Glyphe 'Chamäleon'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde (500)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Chamäleon' schreibt.\n\nGlyphe 'Chamäleon'\nGeringe Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nAufladungen von 'Konzentriertes Feuer' gewähren Euch für jede aktive Aufladung einen visuellen Effekt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104285] = { ["name"] = "Weapon - Sword_2H_Mogu_C_01 - Blue (1H)(Earth Effect)", ["text"] = "Einhändig Schwert\n2 - 5 Schaden Tempo 2.80\n(1.25 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nVerkaufspreis:" }
entries[104286] = { ["name"] = "Zitterndes Feuersturmei", ["text"] = "Accountgebunden\n\"Ein sehr seltenes Ei. Es sieht aus, wie wenn bald etwas daraus schlüpfen würde. Die Älteste Anli im Arboretum würde das sicherlich gerne sehen.\"" }
entries[104287] = { ["name"] = "Windfeder", ["text"] = "Accountgebunden\nBenötigt Stufe 85\nBenutzen: Erhöht 1 Stunde lang das Tempo um 30%, während Ihr ein nicht fliegendes Reittier reitet. Kann nur in Pandaria verwendet werden.\n\"Die Federn des Windfederkranichs sind überraschend leicht und wehen schon beim sanftesten Lufthauch davon.\"" }
entries[104288] = { ["name"] = "Kondensierter Jadenebel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenutzen: Umgebt Euch mit einem dichten Nebel und ermöglicht Euch so, 10 Sek. lang mit den Schatten zu verschmelzen. (5 Min Abklingzeit)\n\"Es heißt, die Jadenebeltänzer seien eins mit dem Nebel, der die Insel umgibt.\"" }
entries[104289] = { ["name"] = "Schwach leuchtendes Kraut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 1 tag (Realzeit)\nBenötigt Stufe 90\nBenutzen: Der Verzehr des Krauts stellt 10 Sek. lang alle 1 Sek. 30000 Gesundheit wieder her.\n\"Diese Pflanze scheint über einen natürlichen Zauber zu verfügen.\"" }
entries[104290] = { ["name"] = "Klebriges Seidenraupenexkret", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenötigt Stufe 90\nBenutzen: Überzieht einen Gegner mit klebriger Seide, wodurch sich selbst das stärkste Geschöpf 20 Sek. lang nicht bewegen kann. (5 Min Abklingzeit)\n\"Die Seidenraupen der Zeitlosen Insel benutzen einen seltsamen, doch sehr starken Seidenfaden, um ihre Beute zu fangen.\"" }
entries[104291] = { ["name"] = "Schwarmling von Gu'chi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Schwarmling von Gu'chi beschwören oder wieder freigeben." }
entries[104292] = { ["name"] = "Halbverdaute Mahlzeit", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Schlange hat offensichtlich viel zu viel auf einmal gefressen, denn das Mahl scheint größtenteils ganz und unverdaut zu sein.\"\n<Zum Öffnen rechtsklicken>" }
entries[104293] = { ["name"] = "Krabblerpanzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Bedeckt Euren Kopf mit einem farbenfrohen Panzer und verringert so 1 Stunde lang den Radius, in dem Gegner Euch entdecken können. (5 Min Abklingzeit)\n\"Die schimmernden Panzer der Dornzangen sind nützlich, um potenzielle Angreifer zu verwirren.\"\nVerkaufspreis:" }
entries[104294] = { ["name"] = "Reif des zeitverlorenen Seefahrers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Singt die eindringliche Melodie der auf dem Schreckensschiff Vazuvius verloren gegangenen Besatzung. (2 Std. Abklingzeit)" }
entries[104295] = { ["name"] = "Harmonisches Stachelschweinchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kaiser Shaohao\n- Respektvoll\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer harmonisches Stachelschwein beschwören oder wieder freigeben." }
entries[104296] = { ["name"] = "Zeremonielle Roben von Ordos", ["text"] = "Wird beim Aufheben gebunden\n\"Diese kunstvoll verzierten verzauberten Roben können in nützliche Bestandteile aufgetrennt werden.\"\n<Zum Öffnen rechtsklicken>" }
entries[104297] = { ["name"] = "Leuchtendes Siegel von Ordos", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Lasst geschmolzene Wut auf alle Kleintiere in einem Umkreis von 40 Metern niedergehen.\nVerkaufspreis:" }
entries[104298] = { ["name"] = "Totenglocke von Ordos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 90\nBenutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 50000 Feuerschaden zu und stößt sie für 3 Sek. auf den Boden. (2 Min Abklingzeit)\n\"Die Anhänger von Ordos läuten diese Glocke, bevor Ordos ein Opfer dargebracht wird.\"\nVerkaufspreis:" }
entries[104299] = { ["name"] = "Flammenschnuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 90\nBenutzen: Schleudert den Benutzer als flammenden Meteor weit weg. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Ein weißglühender Splitter aus dem Inneren von Glutfall.\"\nVerkaufspreis:" }
entries[104300] = { ["name"] = "Knife_1h_firelandsraid_d_01", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Dolch\n8 - 16 Schaden Tempo 1.80\n(6.67 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
entries[104301] = { ["name"] = "Knife_1h_firelandsraid_d_01", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Dolch\n8 - 16 Schaden Tempo 1.80\n(6.67 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
entries[104302] = { ["name"] = "Schwarzflammendolche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Legt die Schwarzflammendolche an, um Eure Treue zu Ordos zu demonstrieren. (1 Stunde Abklingzeit)\n\"Die Champions von Ordos verwenden diese zeremoniellen Dolche.\"\nVerkaufspreis:" }
entries[104303] = { ["name"] = "Regenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Regenstein, der in der Umgebung 10 Min. lang eine unnatürliche Sturzflut auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Die verspielten Wassergeister Pandarias haben eine merkwürdige Verbindung mit dem Wetter.\"\nVerkaufspreis:" }
entries[104304] = { ["name"] = "Blizzardstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Blizzardstein, der in der Umgebung 10 Min. lang einen unnatürlichen Schneesturm auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Ranghohe Sänger von Ordos können das Wetter kontrollieren, sodass nie Schnee oder Regen auf die ewigen Feuer im Heiligtum von Ordos fällt.\"\nVerkaufspreis:" }
entries[104305] = { ["name"] = "Aschestein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Aschestein, der in der Umgebung 10 Min. lang einen Aschesturm auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Bevor sie angreifen, beschwören die Anhänger von Ordos oft einen Aschesturm, der ihren Feinden die Sicht unmöglich macht.\"\nVerkaufspreis:" }
entries[104306] = { ["name"] = "Sonnenuntergangsstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Sonnenuntergangsstein, der die Tageszeit der Umgebung 10 Min. lang zu Sonnenuntergang ändert. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Eine seltsame und potenziell ziemlich gefährliche Kuriosität, die in einem kleinen Gebiet den Fluss der Zeit anhalten kann.\"\nVerkaufspreis:" }
entries[104307] = { ["name"] = "Jadefeuergeist", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Jadefeuergeist beschwören oder wieder freigeben." }
entries[104308] = { ["name"] = "Akoliks säuregetränkte Roben", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n2703 Rüstung\n+3.121 Ausdauer\n+1.840 Intelligenz\nErhöht Eure kritische Trefferwertung um + 1.267.\nErhöht Eure Meisterschaftswertung um + 1.267.\n\nRoter Sockel\nRoter Sockel\nGelber Sockel\nSockelbonus: + 180 Intelligenz\n\nHaltbarkeit 165 / 165\nBenötigt Stufe 90\nVerkaufspreis:" }
entries[104309] = { ["name"] = "Ewiger Flammenkessel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Baut einen ewigen Flammenkessel auf, der die Willenskraft aller in der Nähe um 4 erhöht und das Kochen ermöglicht. (30 Min Abklingzeit)\n\"Anhänger von Ordos nehmen kleine Flammenkessel mit, wenn sie sich auf lange Reisen durch die Wildnis begeben.\"" }
entries[104311] = { ["name"] = "Beinplatten des unüberlegten Streits", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n5720 Rüstung\n+1.840 Stärke\n+3.121 Ausdauer\nErhöht Eure Tempowertung um + 1.288.\nErhöht Eure Meisterschaftswertung um + 1.232.\n\nBlauer Sockel\nBlauer Sockel\nRoter Sockel\nSockelbonus: + 180 Stärke\n\nHaltbarkeit 120 / 120\nBenötigt Stufe 90\nVerkaufspreis:" }
entries[104312] = { ["name"] = "Merkwürdig leuchtender Pilz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenötigt Stufe 90\nBenutzen: Heilt den Benutzer 10 Sek. lang alle 2 Sek. um 5% seiner maximalen Gesundheit und stellt 5% einer klassenspezifischen Primärressource wieder her.\n\"Ein merkwürdiger Pilz aus den Tiefen der Höhle der Verlorenen Geister.\"" }
entries[104313] = { ["name"] = "Goldenes Moos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nAnlegen: Getötete Gegner, die Erfahrung oder Ehre gewähren, können zusätzliche Goldbeute gewähren. (Procchance: 10%, 10Min. Abklingzeit)\n\"Das Moos ist mit Gold und anderen wertvollen Mineralien gespickt, die sich im Laufe von Jahrtausenden in den feuchten Höhlen gebildet haben.\"\nVerkaufspreis:" }
entries[104314] = { ["name"] = "Drachenbrühe", ["text"] = "Benutzen: Ein überraschend starkes alkoholisches Getränk.\n\"Von Grimmdorn Rotbart persönlich hergestellt.\"\nVerkaufspreis:" }
entries[104316] = { ["name"] = "Spektraler Grog", ["text"] = "Benutzen: Verwandelt Euch in einen Spektralpiraten und macht Euch betrunken. (3 Sek. Abklingzeit)\n\"Verströmt ein jenseitiges Aroma.\"\nVerkaufspreis:" }
entries[104317] = { ["name"] = "Miese Helferbox", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren miesen kleinen Helfer beschwören oder wieder freigeben.\n\nSelbst miese kleine Helfer sind das ganze Jahr über sehr beschäftigt und haben deshalb nur während des Winterhauchfests Zeit, Euch zu begleiten." }
entries[104318] = { ["name"] = "Steuerung des Krachbummfliegers", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert Euren Flieger. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[104319] = { ["name"] = "Winterhauchgeschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[104320] = { ["name"] = "Verfluchter Talisman", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Verbannt den Benutzer 20 Sek. lang. (5 Min Abklingzeit)\n50 Aufladungen\n\"Die Schnitzarbeit auf dem Talisman stellt eine Grotte voller Moos dar. Wenn man die Augen zukneift, kann man im Moosbett beinahe ein Gesicht erkennen.\"" }
entries[104321] = { ["name"] = "Kapitän Zvezdans verlorenes Bein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nBenutzen: Stampft mit dem Bein auf den Boden und ruft die Besatzung der Seepocke herbei, um Euch 10 Min. lang im Kampf beizustehen. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[104323] = { ["name"] = "Football", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werft den Ball einem freundlich gesinnten Spieler zu. Wenn möglich, wird er ihn zurückwerfen!\n\"Eine luftgefüllte Schweineblase, die in robustes Rindsleder gewickelt ist.\"\nVerkaufspreis:" }
entries[104324] = { ["name"] = "Fußball", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schießt den Ball einem freundlich gesinnten Spieler zu. Wenn möglich, spielt er ihn automatisch zurück.\n\"Eine luftgefüllte Kodoblase, die in robustes Zhevraleder gewickelt ist.\"\nVerkaufspreis:" }
entries[104325] = { ["name"] = "Wolkenschlange des tyrannischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des tyrannischen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier." }
entries[104326] = { ["name"] = "Wolkenschlange des erbitterten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des erbitterten Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier." }
entries[104327] = { ["name"] = "Wolkenschlange des stolzen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des stolzen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier." }
entries[104328] = { ["name"] = "Kauterisierender Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Aktiviert den Kern und ermöglicht es dem Träger, mit 20% Gesundheit und Mana wiederbelebt zu werden. (1 Stunde Abklingzeit)\n20 Aufladungen\n\"Ein feuriger Kern, der die lebendige Essenz des geschmolzenen Wächters enthält.\"" }
entries[104329] = { ["name"] = "Aschebedecktes Horn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nReittier\nBenötigt Stufe 85\nBenutzen: Beschwört ein reitbares aber unkontrollierbares wütendes Aschefellmushan. Das ist ein sehr, SEHR schnelles Reittier. (1 Min Abklingzeit)\n\"Immer etwas warm.\"" }
entries[104330] = { ["name"] = "Verformtes Warnschild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 90\nBenutzen: Platziert ein Warnschild, was 1 Min. lang bestehen bleibt. In das Schild kann eine Nachricht geschnitzt werden, wodurch es 1 Stunde bestehen bleibt und für andere Spielercharaktere sichtbar wird. (3 Sek. Abklingzeit)\n5 Aufladungen\n\"Das Holz dieses Schilds wird nicht lange Bestand haben.\"" }
entries[104331] = { ["name"] = "Warnschild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 85\nBenutzen: Platziert ein Warnschild, was 1 Min. lang bestehen bleibt. In das Schild kann eine Nachricht geschnitzt werden, wodurch es 1 Stunde bestehen bleibt und für andere Spielercharaktere sichtbar wird. (1 Stunde Abklingzeit)" }
